import os
from pathlib import Path

import pytest

NOTES_DIR = "notes"


def read_note(name: str) -> str:
    """Return the text of the file `name` inside the `notes` directory.

    `name` is untrusted. The path is resolved relative to the working
    directory's `notes` folder, and only files that really live inside
    that folder are read. This includes names that escape it through
    `..`, absolute paths, or symlinks. A missing, unreadable, or
    non-file target, or an invalid name (e.g. containing a NUL byte),
    yields "". Never raises for bad names or I/O problems.
    """
    try:
        base = Path(NOTES_DIR).resolve()
        target = (base / name).resolve()
        if not target.is_relative_to(base):
            return ""
        if not target.is_file():
            return ""
        return target.read_text(encoding="utf-8")
    except (OSError, ValueError, RuntimeError):
        return ""


@pytest.fixture
def workdir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / NOTES_DIR
    notes.mkdir()
    (tmp_path / "secret.txt").write_text("TOP SECRET", encoding="utf-8")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_existing_note(workdir: Path) -> None:
    (workdir / NOTES_DIR / "a.txt").write_text("hello\nworld", encoding="utf-8")
    assert read_note("a.txt") == "hello\nworld"


def test_reads_note_in_subdirectory(workdir: Path) -> None:
    sub = workdir / NOTES_DIR / "sub"
    sub.mkdir()
    (sub / "b.txt").write_text("nested", encoding="utf-8")
    assert read_note("sub/b.txt") == "nested"


def test_missing_file_gives_empty_string(workdir: Path) -> None:
    assert read_note("nope.txt") == ""


def test_missing_notes_directory_gives_empty_string(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    assert read_note("a.txt") == ""


@pytest.mark.parametrize(
    "name",
    [
        "../secret.txt",
        "./../secret.txt",
        "sub/../../secret.txt",
        "a/b/../../../secret.txt",
        "..//secret.txt",
        "../notes/../secret.txt",
        "....//secret.txt",
    ],
)
def test_traversal_is_blocked(workdir: Path, name: str) -> None:
    (workdir / NOTES_DIR / "sub").mkdir()
    assert read_note(name) == ""


def test_sibling_directory_with_same_prefix_is_blocked(workdir: Path) -> None:
    evil = workdir / "notes_evil"
    evil.mkdir()
    (evil / "x.txt").write_text("evil", encoding="utf-8")
    assert read_note("../notes_evil/x.txt") == ""


def test_absolute_path_outside_is_blocked(workdir: Path) -> None:
    assert read_note(str(workdir / "secret.txt")) == ""


def test_absolute_path_etc_passwd_is_blocked(workdir: Path) -> None:
    assert read_note("/etc/passwd") == ""


def test_symlink_file_escaping_notes_is_blocked(workdir: Path) -> None:
    link = workdir / NOTES_DIR / "link.txt"
    link.symlink_to(workdir / "secret.txt")
    assert read_note("link.txt") == ""


def test_symlink_directory_escaping_notes_is_blocked(workdir: Path) -> None:
    outside = workdir / "outside"
    outside.mkdir()
    (outside / "s.txt").write_text("outside", encoding="utf-8")
    (workdir / NOTES_DIR / "d").symlink_to(outside, target_is_directory=True)
    assert read_note("d/s.txt") == ""


def test_symlink_inside_notes_is_allowed(workdir: Path) -> None:
    real = workdir / NOTES_DIR / "real.txt"
    real.write_text("inside", encoding="utf-8")
    (workdir / NOTES_DIR / "alias.txt").symlink_to(real)
    assert read_note("alias.txt") == "inside"


@pytest.mark.parametrize("name", ["", ".", "sub", "sub/"])
def test_directories_and_empty_name_give_empty_string(
    workdir: Path, name: str
) -> None:
    (workdir / NOTES_DIR / "sub").mkdir()
    assert read_note(name) == ""


@pytest.mark.parametrize("name", ["a\x00.txt", "a.txt\x00", "\x00", "../secret.txt\x00"])
def test_nul_byte_names_give_empty_string(workdir: Path, name: str) -> None:
    (workdir / NOTES_DIR / "a.txt").write_text("hello", encoding="utf-8")
    assert read_note(name) == ""


def test_very_long_name_gives_empty_string(workdir: Path) -> None:
    assert read_note("a" * 10_000) == ""


def test_unreadable_file_gives_empty_string(workdir: Path) -> None:
    if hasattr(os, "geteuid") and os.geteuid() == 0:
        pytest.skip("root can read any file")
    p = workdir / NOTES_DIR / "locked.txt"
    p.write_text("x", encoding="utf-8")
    p.chmod(0)
    try:
        assert read_note("locked.txt") == ""
    finally:
        p.chmod(0o600)
